import collections
out=w/'breadth';data=json.loads((out/'record.json').read_text());audit=json.loads((out/'array-review.json').read_text());build=json.loads((w/'build.json').read_text());native=json.loads((w/'native-record.json').read_text());sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
