summary={'complete':not pending,'scope':audit['scope'],'images':data['images'],'distinct_functions':data['distinct_functions'],'language_function_records':data['language_function_records'],'changed_rust_records':len(keys),'variable_provenance_records':metadata['changed_variable_records'],'variable_identity_type_storage_unchanged':True,'metadata_report_sha256':sha(out/'metadata-review.json'),'classified_records':len(keys)-len(pending),'pending_records':len(pending),'array_zero_stores':sum(x.get('array_zero_stores')or 0 for x in audit['records']),'c_go_records_unchanged':True,'native_complete_bodies':13,'native_function_comparisons':416,'new_decompiler_errors':0,'new_rust_parse_errors':0,'existing_rust_parse_failures':parse[(True,True)],'rust_parse_failures_resolved':parse[(True,False)],'identifier_normalized_records':sum(x['identifier_normalization_only']for x in audit['records']),'ast_report_sha256':sha(out/'array-review.json'),'audit_source_sha256':sha(w/'ast-audit/src/main.rs'),'audit_binary_sha256':sha(w/'ast-audit/target/release/kuna-rust-array-zero-audit'),'limitations':['Whole-program native equivalence and full runtime type correctness are not established by structural comparison.','New byte-array element counts are recorded; old scalar syntax alone cannot prove the destination storage width.','The unchanged STORE address must designate valid writable storage; arbitrary pointers are not covered.','Nonzero/nonconstant values, other element types and scalar STORE-width mismatches are outside this change.','Raw inherited parser failures retain diagnostics; identifier-only normalization is review-only.','Registered native proof is x86_64 with Rust overflow-checks=off and C-fwrapv. No multiarchitecture native parity claim.'],'pending':pending}
(out/'structural-review.json').write_text(json.dumps(summary,indent=2)+'\n');print('Array zero review',len(keys),'changes;',len(pending),'pending');assert summary['complete'],'Review pending records before timing or publication'
